cd /testbed && python3 -c "
# Check if all occurrences are fullwidth underscore replacing regular underscore
import os

for root, dirs, files in os.walk('tests/files'):
    for f in files:
        filepath = os.path.join(root, f)
        try:
            with open(filepath, 'rb') as file:
                content = file.read()
                if b'\xef\xbc\xbf' in content:
                    # Check if it's replacing underscore
                    has_underscore = b'_' in content
                    print(f'{filepath}: has regular underscore={has_underscore}')
        except:
            pass
