cd /testbed && python3 -c "
import os

# Check what non-ASCII bytes are in the files
for root, dirs, files in os.walk('tests/files'):
    for f in files:
        filepath = os.path.join(root, f)
        try:
            with open(filepath, 'rb') as file:
                content = file.read()
                # Find all non-ASCII bytes
                non_ascii = set()
                for b in content:
                    if b > 127:
                        non_ascii.add(b)
                if non_ascii:
                    print(f'{filepath}: {sorted(non_ascii)}')
        except:
            pass
" | head -30

