cd /testbed && python3 -c "
# Check the actual UTF-8 sequences in the files
import os

# Read a file and find UTF-8 sequences
with open('tests/files/dbc/bus_comment.dbc', 'rb') as f:
    content = f.read()

# Find all bytes > 127 and group them into UTF-8 sequences
i = 0
while i < len(content):
    b = content[i]
    if b > 127:
        # Start of a multi-byte sequence
        if b >= 0xF0:
            seq = content[i:i+4]
        elif b >= 0xE0:
            seq = content[i:i+3]
        elif b >= 0xC0:
            seq = content[i:i+2]
        else:
            seq = content[i:i+1]

        try:
            char = seq.decode('utf-8')
            print(f'{i:5d}: {seq.hex()} = {repr(char)} (U+{ord(char):04X})')
        except:
            print(f'{i:5d}: {seq.hex()} = <invalid>')
        i += len(seq)
    else:
        i += 1
" | head -40

